    initial_bounds = {name: (low, high) for name, (low, high) in roots.items()}

    def search(assigned, bounds):
        nonlocal best_versions, best_vector

        pending = sorted(bounds.keys() - assigned.keys())
        if not pending:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(assigned)
            return

        name = pending[0]
        low, high = bounds[name]
        for row in packages.get(name, []):
            version = row['version']
            if not low <= version <= high:
                continue
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_bounds = dict(bounds)
            feasible = True

            for dep in row['deps']:
                dep_name = dep['name']
                dep_low, dep_high = dep['min'], dep['max']
                old = next_bounds.get(dep_name)
                if old is not None:
                    dep_low = max(dep_low, old[0])
                    dep_high = min(dep_high, old[1])
                if dep_low > dep_high:
                    feasible = False
                    break
                next_bounds[dep_name] = (dep_low, dep_high)
                if dep_name in next_assigned:
                    dep_version = next_assigned[dep_name]
                    if not dep_low <= dep_version <= dep_high:
                        feasible = False
                        break

            if feasible:
                search(next_assigned, next_bounds)

